std::shared_ptr<Ticket> park(std::shared_ptr<Vehicle> vehicle) {
  VehicleSize size = vehicle->getSize();
  std::optional<ParkingSpot> spot = allocator.allocate(size);   // must be atomic — see W. Concurrency
  if (!spot.has_value()) throw NoAvailableSpotException();
  spot->occupy(vehicle);
  auto ticket = Ticket::create(vehicle, *spot, now());
  return ticket;
}

Fee unpark(std::shared_ptr<Ticket> ticket) {
  if (ticket->status != ACTIVE) throw InvalidTicketException();
  ticket->close(now());
  Fee fee = feeStrategy.calculate(ticket);
  ticket->spot.vacate();
  return fee;
}

