  VehicleSize size = vehicle.getSize();
  Optional<ParkingSpot> spot = allocator.allocate(size);   // must be atomic — see W. Concurrency
  if (spot.isEmpty()) throw new NoAvailableSpotException();
  spot.get().occupy(vehicle);
  Ticket ticket = Ticket.create(vehicle, spot.get(), now());
  return ticket;
}

