class Cache {
public:
  virtual std::optional<V> get(const K& key) = 0;
  virtual void put(const K& key, const V& value) = 0;
};

template <typename K, typename V>
class LRUCache : public Cache<K, V> {
public:
  explicit LRUCache(int capacity);          // throws std::invalid_argument if capacity <= 0
  std::optional<V> get(const K& key);       // O(1); updates recency
  void put(const K& key, const V& value);   // O(1); may trigger eviction
};

