RateLimitResult allowRequest(const std::string& key, long now) {
  auto bucket = store.getOrCreate(key, capacity);
  std::lock_guard<std::mutex> lock(bucket->mutex);
  long elapsed = now - bucket->lastRefillTime;
  bucket->tokens = std::min(capacity, bucket->tokens + elapsed * refillRatePerMs);
  bucket->lastRefillTime = now;
  if (bucket->tokens >= 1) {
    bucket->tokens -= 1;
    return ALLOW(/* remaining = */ std::floor(bucket->tokens));
  } else {
    double deficit = 1 - bucket->tokens;
    return DENY(/* retryAfterMs = */ deficit / refillRatePerMs);
  }
}

