Expense addExpense(Money total, User payer, std::vector<User> participants,
                    SplitType type, std::map<std::string, std::any> params) {
  auto strategy = strategyFactory.get(type);
  auto splits = strategy->compute(total, participants, params);
  assert(sum(splits, [](const Split& s) { return s.amount; }) == total);   // reject if strategy is buggy
  Expense expense = Expense::create(total, payer, splits);
  for (const auto& split : splits) {
    if (split.user != payer) {
      balanceSheet.adjust(split.user, payer, +split.amount);   // split.user owes payer
    }
  }
  return expense;
}

Payment settleUp(User from, User to, Money amount, const std::string& idemKey) {
  if (paymentLog.seen(idemKey)) return paymentLog.get(idemKey);   // idempotent replay
  balanceSheet.adjust(from, to, -amount);
  Payment payment = Payment::create(from, to, amount);
  paymentLog.record(idemKey, payment);
  return payment;
}

