  Expense expense = Expense.create(total, payer, splits);
  for (Split split : splits) {
    if (!split.user.equals(payer)) {
      balanceSheet.adjust(split.user, payer, split.amount);   // split.user owes payer
    }
  }
  return expense;
}

Payment settleUp(User from, User to, Money amount, String idemKey) {
  if (paymentLog.seen(idemKey)) return paymentLog.get(idemKey);   // idempotent replay
  balanceSheet.adjust(from, to, amount.negate());
  Payment payment = Payment.create(from, to, amount);
  paymentLog.record(idemKey, payment);
  return payment;
}

