Ride requestRide(std::shared_ptr<Rider> rider, Location pickup, Location dropoff) {
  Ride ride = Ride::create(rider, pickup, dropoff, REQUESTED);
  auto candidates = geoIndex.findNearby(pickup, DEFAULT_RADIUS);
  while (!candidates.empty()) {
    auto driver = matchingStrategy.match(ride, candidates);
    if (!driver.has_value()) break;
    if (driver->tryReserve()) {          // atomic CAS: AVAILABLE -> RESERVED
      ride.transitionTo(MATCHED, *driver);
      notificationService.onRideStatusChanged(ride);
      return ride;
    }
    candidates.erase(std::remove(candidates.begin(), candidates.end(), *driver), candidates.end());   // someone else grabbed it first, retry
  }
  ride.transitionTo(NO_DRIVER_FOUND);
  return ride;
}

Ride completeRide(const std::string& rideId) {
  Ride ride = rides.get(rideId);
  ride.transitionTo(COMPLETED);        // throws if not currently IN_PROGRESS
  Money baseFare = fareStrategy.calculate(ride);   // may itself be a decorator chain
  ride.fare = baseFare;
  paymentGateway.charge(ride.rider, baseFare);
  driver->release();                   // RESERVED/ON_TRIP -> AVAILABLE
  notificationService.onRideStatusChanged(ride);
  return ride;
}

