void notify(String userId, Category category, String templateId,
            Map<String, Object> params, List<ChannelType> channels, String idemKey) {
  if (dedupeCache.seen(idemKey)) return;                        // idempotent replay guard
  for (ChannelType channel : channels) {
    if (!userPreference.isAllowed(userId, channel, category)) continue;
    if (!rateLimiter.tryAcquire(userId, channel)) continue;
    RenderedContent content = template.render(templateId, channel, params);
    DeliveryResult result = channelImpl(channel).send(content, resolveAddress(userId, channel));
    if (result.failed()) {
      retryScheduler.scheduleRetry(notification, 1);
    }
  }
  dedupeCache.record(idemKey);
}

void onRetryDue(Notification notification, int attempt) {
