void dispenseNow() {
  Recipe recipe = this.selectedBeverage.getRecipe();
  List<Reservation> reserved = new ArrayList<>();
  for (Map.Entry<Ingredient, Integer> entry : recipe.getRequirements().entrySet()) {
    Ingredient ingredient = entry.getKey();
    int qty = entry.getValue();
    if (!ingredient.tryReserve(qty)) {                    // atomic check-and-decrement
      for (Reservation r : reserved) r.getIngredient().release(r.getQty());   // roll back partial reservation
      this.paymentMethod.refund(recipe.getPrice());
      this.state = new OutOfStockState();
      return;
    }
    reserved.add(new Reservation(ingredient, qty));
  }
  // all ingredients reserved successfully — safe to physically dispense
  dispenser.pour(recipe);
  this.state = new IdleState();
}

