move(source: Path, destination: Path): void {
  const srcParent: Directory = this.resolveParent(source);
  const destParent: Directory = this.resolveParent(destination);
  const node: FileSystemNode = srcParent.getChild(source.lastSegment);

  if (node instanceof Directory && destination.isDescendantOf(source)) {
    throw new Error("cannot move a directory into its own subtree");    // IllegalMoveException
  }

  // lock ordering: always acquire in canonical-path order to prevent
  // an ABBA deadlock against a concurrent move() going the other direction
  const [first, second] = orderByCanonicalPath(srcParent, destParent);
  lock(first); lock(second);
  try {
    srcParent.removeChild(node.name);
    node.parent = destParent;
    destParent.addChild(node);
  } finally {
    unlock(second); unlock(first);
  }
}

visitDirectory(d: Directory): void {
  let total = 0;
  for (const child of d.children.values()) {
    child.accept(this);               // recurses; visitFile adds file.size directly
    total += this.lastSize;
  }
  this.lastSize = total;
}

