void publish(Message message) {
  for (Subscription subscription : this.subscriptions) {
    if (!subscription.getQueue().tryEnqueue(message)) {      // bounded queue full
      subscription.getOverflowPolicy().onOverflow(subscription, message);
    }
  }
}

void consumeLoop() {                                          // one per subscriber, background thread
  while (running) {
    Message message = this.queue.take();
    try {
      this.subscriber.onMessage(message);                     // must be idempotent — may be a redelivery
      this.ack(message.getId());
    } catch (Exception e) {
      this.nack(message.getId());
    }
  }
}

