TransactionResult execute(Account account, BankServer bank) {
  DebitResult result = bank.debit(account, amount);     // atomic at the bank: check-and-deduct as one op
  if (!result.isSuccess()) return TransactionResult.INSUFFICIENT_FUNDS;
  try {
    atm.dispense(amount);
  } catch (DispenseFailureException e) {
    bank.credit(account, amount);           // compensating action — never leave a debit stranded
    return TransactionResult.DISPENSE_FAILED;
  }
  return TransactionResult.SUCCESS;
}

void handle(int amount) throws InsufficientCashException {
  int count = Math.min(amount / this.value, this.availableCount);
  dispense(count, this.value);
  int remainder = amount - (count * this.value);
  if (remainder > 0 && next != null) next.handle(remainder);
  else if (remainder > 0) throw new InsufficientCashException();
}

