Reservation bookRoom(Guest guest, ReservationRequest request) {
  Room candidateRoom = pickCandidate(request.getRoomType());
  lock(candidateRoom.getInventory());
  try {
    if (!candidateRoom.getInventory().isAvailable(request.getRange())) { reject(); }
    candidateRoom.getInventory().book(request.getRange());
    Money price = pricingStrategyFor(candidateRoom).calculatePrice(candidateRoom, request.getRange());
    Reservation reservation = new Reservation(guest, candidateRoom, request.getRange(), price);
    bookingNotifier.notifyConfirmed(reservation);
    return reservation;
  } finally {
    unlock(candidateRoom.getInventory());
  }
}

