SeatLock holdSeats(User user, Show show, List<SeatId> seatIds) {
  List<SeatId> orderedIds = sort(seatIds);          // canonical order — see W
  List<ShowSeat> locks = new ArrayList<>();
  try {
    for (SeatId id : orderedIds) {
      lock(showSeatFor(id));
      locks.add(showSeatFor(id));
      if (showSeatFor(id).getStatus() != AVAILABLE) { rollback(locks); reject(); }
    }
    for (ShowSeat seat : locks) { seat.setStatus(LOCKED); }
    SeatLock seatLock = new SeatLock(user, locks, /* expiresAt = */ now().plus(HOLD_TTL));
    return seatLock;
  } finally {
    for (ShowSeat seat : locks) { unlock(seat); }
  }
}

