Message send(User sender, String content) {
  Message message;
  lock(this.sequenceCounter);
  try {
    long seq = ++this.nextSequence;      // server-assigned, monotonic per conversation
    message = new Message(sender, content, seq);
  } finally {
    unlock(this.sequenceCounter);
  }
  this.messages.add(message);
  for (User participant : this.participants) {      // Observer fan-out
    if (presenceTracker.isOnline(participant)) {
      deliver(participant, message);
    } else {
      offlineQueueFor(participant).enqueue(message);
    }
  }
  return message;
}

List<Message> reconnect(User user, long lastSeenSequence) {
  List<Message> missed = offlineQueueFor(user).allAfter(lastSeenSequence);   // idempotent: same cursor -> same result
  offlineQueueFor(user).clearUpTo(lastSeenSequence + missed.size());
  return missed;
}

